-- =====================================================================
-- HOUSE ROBOTICS — USA National SEO & Location Management Migration
-- MySQL / MariaDB compatible for cPanel phpMyAdmin execution
-- Generated for Phase 2 Rollout (51 States, 284 Cities, 18 Pilot Pages)
-- =====================================================================

SET FOREIGN_KEY_CHECKS = 0;

-- 1. Create usa_states table
CREATE TABLE IF NOT EXISTS `usa_states` (
  `id` varchar(36) NOT NULL,
  `name` varchar(100) NOT NULL,
  `code` varchar(10) NOT NULL,
  `slug` varchar(100) NOT NULL,
  `region` varchar(50) NOT NULL,
  `capital` varchar(100) NOT NULL,
  `major_industries` text NOT NULL,
  `economic_overview` text NOT NULL,
  `seo_title` varchar(255) DEFAULT NULL,
  `meta_description` text DEFAULT NULL,
  `status` varchar(50) NOT NULL DEFAULT 'PUBLISHED',
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_state_slug` (`slug`),
  UNIQUE KEY `idx_state_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 2. Create usa_cities table
CREATE TABLE IF NOT EXISTS `usa_cities` (
  `id` varchar(36) NOT NULL,
  `state_id` varchar(36) NOT NULL,
  `state_slug` varchar(100) NOT NULL,
  `name` varchar(150) NOT NULL,
  `slug` varchar(150) NOT NULL,
  `county` varchar(150) NOT NULL,
  `metro_area` varchar(200) NOT NULL,
  `population` int(11) NOT NULL DEFAULT 0,
  `population_year` varchar(100) NOT NULL DEFAULT '2023 US Census',
  `major_industries` text NOT NULL,
  `digital_demand_tier` varchar(50) NOT NULL DEFAULT 'High',
  `priority_tier` int(11) NOT NULL DEFAULT 1,
  `commercial_profile` text NOT NULL,
  `remote_delivery_fit` text NOT NULL,
  `seo_title` varchar(255) DEFAULT NULL,
  `meta_description` text DEFAULT NULL,
  `focus_keyword` varchar(150) DEFAULT NULL,
  `status` varchar(50) NOT NULL DEFAULT 'PUBLISHED',
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_city_state_slug` (`state_slug`, `slug`),
  KEY `idx_city_priority` (`priority_tier`),
  KEY `idx_city_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 3. Create usa_location_pages table
CREATE TABLE IF NOT EXISTS `usa_location_pages` (
  `id` varchar(36) NOT NULL,
  `page_type` varchar(50) NOT NULL DEFAULT 'CITY_SERVICE',
  `state_slug` varchar(100) NOT NULL,
  `city_slug` varchar(150) DEFAULT NULL,
  `service_slug` varchar(150) DEFAULT NULL,
  `url_path` varchar(255) NOT NULL,
  `h1_title` varchar(255) NOT NULL,
  `hero_kicker` varchar(255) DEFAULT NULL,
  `hero_subtitle` text DEFAULT NULL,
  `meta_title` varchar(255) NOT NULL,
  `meta_description` text NOT NULL,
  `focus_keyword` varchar(150) DEFAULT NULL,
  `secondary_keywords` text DEFAULT NULL,
  `canonical_url` varchar(255) NOT NULL,
  `og_title` varchar(255) DEFAULT NULL,
  `og_description` text DEFAULT NULL,
  `og_image` varchar(255) DEFAULT NULL,
  `content_intro` text NOT NULL,
  `local_industry_focus` longtext DEFAULT NULL,
  `business_problems_solved` longtext DEFAULT NULL,
  `service_deliverables` longtext DEFAULT NULL,
  `suitable_customer_types` longtext DEFAULT NULL,
  `remote_collaboration_model` text DEFAULT NULL,
  `process_steps` longtext DEFAULT NULL,
  `illustrative_scenarios` longtext DEFAULT NULL,
  `faqs` longtext DEFAULT NULL,
  `quality_gate_passed` tinyint(1) NOT NULL DEFAULT 1,
  `quality_review_notes` text DEFAULT NULL,
  `verified_at` datetime DEFAULT NULL,
  `status` varchar(50) NOT NULL DEFAULT 'PUBLISHED',
  `no_index` tinyint(1) NOT NULL DEFAULT 0,
  `leads_count` int(11) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_page_url_path` (`url_path`),
  KEY `idx_page_state_city_service` (`state_slug`, `city_slug`, `service_slug`),
  KEY `idx_page_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 4. Extend leads and contact_messages with city and state columns safely
SET @dbname = DATABASE();
SET @tablename = 'leads';
SET @columnname = 'city';
SET @preparedStatement = (SELECT IF(
  (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = @dbname AND TABLE_NAME = @tablename AND COLUMN_NAME = @columnname) > 0,
  'SELECT 1',
  'ALTER TABLE `leads` ADD COLUMN `city` varchar(100) DEFAULT NULL AFTER `company`'
));
PREPARE alterIfNotExists FROM @preparedStatement;
EXECUTE alterIfNotExists;
DEALLOCATE PREPARE alterIfNotExists;

SET @columnname = 'state';
SET @preparedStatement = (SELECT IF(
  (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = @dbname AND TABLE_NAME = @tablename AND COLUMN_NAME = @columnname) > 0,
  'SELECT 1',
  'ALTER TABLE `leads` ADD COLUMN `state` varchar(100) DEFAULT NULL AFTER `city`'
));
PREPARE alterIfNotExists FROM @preparedStatement;
EXECUTE alterIfNotExists;
DEALLOCATE PREPARE alterIfNotExists;

SET @tablename = 'contact_messages';
SET @columnname = 'city';
SET @preparedStatement = (SELECT IF(
  (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = @dbname AND TABLE_NAME = @tablename AND COLUMN_NAME = @columnname) > 0,
  'SELECT 1',
  'ALTER TABLE `contact_messages` ADD COLUMN `city` varchar(100) DEFAULT NULL AFTER `company`'
));
PREPARE alterIfNotExists FROM @preparedStatement;
EXECUTE alterIfNotExists;
DEALLOCATE PREPARE alterIfNotExists;

SET @columnname = 'state';
SET @preparedStatement = (SELECT IF(
  (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = @dbname AND TABLE_NAME = @tablename AND COLUMN_NAME = @columnname) > 0,
  'SELECT 1',
  'ALTER TABLE `contact_messages` ADD COLUMN `state` varchar(100) DEFAULT NULL AFTER `city`'
));
PREPARE alterIfNotExists FROM @preparedStatement;
EXECUTE alterIfNotExists;
DEALLOCATE PREPARE alterIfNotExists;

